#include "stdlib/math/base/special/round2f.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/assert/is_infinitef.h"
#include "stdlib/math/base/special/frexpf.h"
#include "stdlib/math/base/special/scalbnf.h"

/**
* Rounds a single-precision floating-point value to the nearest power of two on a linear scale.
*
* @param x    input value
* @return     rounded value
*
* @example
* float out = stdlib_base_round2f( 3.14f );
* // returns 4.0f
*/
float stdlib_base_round2f( const float x ) {
	float m;
	float y;
	float sign;
	int e;

	// Handle special cases:
	if ( stdlib_base_is_nanf( x ) || stdlib_base_is_infinitef( x ) || x == 0.0f ) {
		return x;
	}

	// Preserve sign:
	if ( x < 0.0f ) {
		sign = -1.0f;
		m = -x;
	} else {
		sign = 1.0f;
		m = x;
	}

	// Decompose: m = frac * 2^e, frac in [0.5, 1):
	m = stdlib_base_frexpf( m, &e );

	// Decide nearest power of two:
	if ( m < 0.75f ) {
		y = stdlib_base_scalbnf( 1.0f, e-1 );
	} else {
		y = stdlib_base_scalbnf( 1.0f, e );
	}

	return sign * y;
}
